import { afterEach, describe, expect, test } from "vitest";
import { CALENDAR } from "../../shared/constants";
import {
  decryptSecret,
  encryptSecret,
  requireEncryptionKey,
} from "./secrets";

/**
 * `CALENDAR_TOKEN_KEY` is generated by hand with `openssl rand`, so whatever
 * that command printed is what lands in the deployment environment. These
 * tests pin every spelling the parser promises to accept — including the
 * standard-base64 form, whose `+` and `/` a URL-safe decoder drops, which
 * would make a perfectly good key look missing.
 */

const original = process.env.CALENDAR_TOKEN_KEY;

afterEach(() => {
  if (original === undefined) delete process.env.CALENDAR_TOKEN_KEY;
  else process.env.CALENDAR_TOKEN_KEY = original;
});

/** 32 bytes whose standard-base64 spelling is full of `+` and `/`. */
const KEY_BYTES = Uint8Array.from(
  { length: 32 },
  (_, index) => [0xfb, 0xef, 0xbe][index % 3],
);

describe("CALENDAR_TOKEN_KEY", () => {
  test("standard base64 from `openssl rand -base64 32` is accepted", () => {
    const spelling = Buffer.from(KEY_BYTES).toString("base64");
    // Fixture sanity: if this stops containing `+`/`/` it proves nothing.
    expect(spelling).toMatch(/[+/]/);
    process.env.CALENDAR_TOKEN_KEY = spelling;
    expect([...requireEncryptionKey()]).toEqual([...KEY_BYTES]);
  });

  test("base64url and hex spellings decode to the same key", () => {
    process.env.CALENDAR_TOKEN_KEY =
      Buffer.from(KEY_BYTES).toString("base64url");
    expect([...requireEncryptionKey()]).toEqual([...KEY_BYTES]);

    process.env.CALENDAR_TOKEN_KEY = Buffer.from(KEY_BYTES).toString("hex");
    expect([...requireEncryptionKey()]).toEqual([...KEY_BYTES]);
  });

  test("a key that is not 32 bytes is refused, not silently weakened", () => {
    process.env.CALENDAR_TOKEN_KEY = Buffer.alloc(31, 7).toString("base64");
    expect(() => requireEncryptionKey()).toThrow(CALENDAR.keyMissing);
  });

  test("values sealed under a parsed key round-trip", async () => {
    process.env.CALENDAR_TOKEN_KEY = Buffer.from(KEY_BYTES).toString("base64");
    const sealed = await encryptSecret("refresh-token");
    expect(sealed.startsWith("v1.")).toBe(true);
    expect(sealed).not.toContain("refresh-token");
    expect(await decryptSecret(sealed)).toBe("refresh-token");
  });
});
